const e={promise:{headline:"Sistemas de automatización con IA que hacen funcionar tu trabajo diario.",subline:"Para clínicas y pequeñas empresas: cada lead respondido, cada documento procesado, cada seguimiento enviado — 24/7, sin contratar más personal."},systems:{capture:{name:"Sistema de captación",productLabel:"WhatsApp AI · LeadFire",headline:"Cada consulta respondida en segundos, en el idioma del cliente, 24/7.",replaces:"Mensajes perdidos y respuestas lentas",description:"Un agente de IA en tu número de WhatsApp Business (y en el chat web) que responde preguntas, califica al lead, recopila las fotos para tu médico cuando procede y reserva la cita directamente en tu calendario — en el momento en que llega el mensaje.",outcomes:["Respuestas en menos de 3 segundos en WhatsApp, día y noche","El idioma del cliente se detecta automáticamente","Leads calificados con cita reservada, no solo respondidos"],products:[{name:"WhatsApp AI",oneLiner:"Agente de IA 24/7 en WhatsApp que responde, califica y reserva."},{name:"LeadFire",oneLiner:"Primera respuesta instantánea a cada nuevo lead de anuncios, formularios y chat."}]},convert:{name:"Sistema de seguimiento",productLabel:"Secuencias de seguimiento · Reactivación de leads",headline:"Los leads que dejaron de responder reciben seguimiento — automáticamente, hasta que reservan o se dan de baja.",replaces:"Leads que se enfrían",description:"Seguimiento en varios pasos por WhatsApp, email y SMS para los nuevos leads, además de campañas de reactivación para contactos antiguos que ya están en tu CRM o en tu bandeja de entrada. Se detiene en cuanto alguien responde o reserva.",outcomes:["Ningún lead olvidado tras el primer mensaje","Contactos antiguos recontactados con un mensaje personal","Traspaso a tu equipo cuando hace falta una persona"],products:[{name:"Secuencias de seguimiento",oneLiner:"Secuencias de seguimiento automatizadas para cada nuevo lead."},{name:"Reactivación de leads",oneLiner:"Reactiva leads antiguos y clientes anteriores de tu base de datos."}]},operate:{name:"Sistema de operaciones",productLabel:"Procesamiento de documentos · Agentes de IA para tareas diarias",headline:"Facturas, formularios e introducción de datos gestionados por agentes de IA en lugar de tu equipo.",replaces:"Papeleo e introducción de datos manuales",description:"Agentes de IA que leen los documentos entrantes, extraen los datos, actualizan tus sistemas y envían los recordatorios y seguimientos internos que hoy tu equipo hace a mano — facturas, formularios de admisión, contratos, solicitudes de RR. HH.",outcomes:["Documentos procesados el mismo día en que llegan","Precisión verificada por una persona en lo que importa","Menos introducción manual de datos para tu equipo"],products:[{name:"Procesamiento de documentos",oneLiner:"Lee documentos e introduce los datos donde corresponde."},{name:"Agentes de IA para tareas diarias",oneLiner:"Recordatorios, seguimientos internos y actualizaciones rutinarias, hechos automáticamente."}]},measure:{name:"Sistema de informes",productLabel:"Informe semanal",headline:"Cada lunes, un informe en lenguaje claro sobre leads, ventas y rendimiento del equipo.",replaces:"No saber qué está funcionando",description:"La IA extrae las cifras de tus herramientas — WhatsApp, CRM, anuncios, calendario, contabilidad — y envía un breve informe semanal con lo que ha cambiado, lo que hay que corregir y dónde conviene redoblar esfuerzos.",outcomes:["Un informe semanal en lugar de cinco paneles","Tiempos de respuesta y conversión medidos por ti","Decisiones basadas en números, no en suposiciones"],products:[{name:"Informe semanal",oneLiner:"Informe semanal de rendimiento, cada lunes por la mañana."}]}},addOns:[{name:"Meta Ads",oneLiner:"Campañas de Facebook e Instagram para clínicas, respondidas en WhatsApp en segundos."},{name:"Google Ads",oneLiner:"Campañas de búsqueda para pacientes que ya buscan tu tratamiento."},{name:"SEO y artículos de blog",oneLiner:"Tráfico orgánico con artículos automatizados y optimizados para buscadores."}],audiences:{clinics:{name:"Clínicas y salud",navLabel:"Clínicas",tagline:"Convierte cada consulta de paciente en una cita reservada.",description:"Clínicas de trasplante capilar, dentales, de cirugía estética y de FIV — incluidos los proveedores de turismo médico que atienden a pacientes de Alemania, Reino Unido, Países Bajos y el Golfo.",examples:["Clínicas de trasplante capilar","Clínicas dentales","Cirugía estética","FIV y fertilidad","Agencias de turismo médico"]},"small-business":{name:"Pequeñas empresas",navLabel:"Pequeñas empresas",tagline:"Funciona con IA sin contratar más personal.",description:"Empresas de servicios que viven en WhatsApp, el email y las hojas de cálculo — sobre todo agencias inmobiliarias — y que usan los mismos sistemas que construimos para clínicas.",examples:["Agencias inmobiliarias","Empresas de servicios en WhatsApp"]}}},a={systemsData:e};export{a as default,e as systemsData};
